"""Inject only an authorized PUBLIC OAuth client identifier, never a secret."""
import json
import os
import re
from pathlib import Path

client_id = os.environ.get("TRAKT_CLIENT_ID", "").strip()
if client_id and not re.fullmatch(r"[A-Za-z0-9_-]+", client_id):
    raise SystemExit("Invalid TRAKT_CLIENT_ID format")
path = Path(__file__).resolve().parents[1] / "entry/src/main/ets/config/TraktConfig.ets"
path.write_text(
    "// Generated by CI. Public application identifier only.\n"
    + "export const TRAKT_CLIENT_ID: string = " + json.dumps(client_id) + ";\n"
    + "export const TRAKT_REDIRECT_URI: string = 'showlyharmony://trakt';\n",
    encoding="utf-8",
)
print("Trakt application configured" if client_id else "Trakt not configured; offline preview")
